const copy={editorial:{eyebrow:'Independent editorial',title:'Design with a point of view.',body:'A high-contrast, art-directed direction with deliberate whitespace and a clear reading order.',cta:'Discover the collection'},utilitarian:{eyebrow:'Task-first interface',title:'Clarity beats spectacle.',body:'A dense, pragmatic interface. Information comes first, with visible status and obvious next actions.',cta:'Open the workspace'},immersive:{eyebrow:'Immersive studio',title:'Ideas deserve another dimension.',body:'Full-bleed spatial composition, expressive lighting, and semantic HTML controls.',cta:'Enter the experience'}};
const stage=document.querySelector('#stage'),status=document.querySelector('#status');let current='editorial';
function render(kind){current=kind;const d=copy[kind];stage.replaceChildren();const article=document.createElement('article');article.className=kind;const eyebrow=document.createElement('span');eyebrow.textContent=d.eyebrow;const title=document.createElement('h2');title.textContent=d.title;const body=document.createElement('p');body.textContent=d.body;const btn=document.createElement('button');btn.textContent=d.cta;btn.onclick=()=>status.textContent=`Prototype action triggered (${kind}); no external request.`;article.append(eyebrow,title,body,btn);stage.append(article);document.querySelectorAll('[data-v]').forEach(el=>el.setAttribute('aria-pressed',String(el.dataset.v===kind)))}
document.querySelectorAll('[data-v]').forEach(el=>el.addEventListener('click',()=>render(el.dataset.v)));
document.querySelector('#pick').addEventListener('click',()=>{const report={variant:current,chosenAt:new Date().toISOString(),localOnly:true};status.textContent=`Selected: ${current}. ${JSON.stringify(report)}. Record this decision in a new project plan, never overwrite production automatically.`});render(current);
